/* AUTO-GENERATED PWA SERVICE WORKER (SOURCE OF TRUTH: /assets/pwa/sw.js)
 * Pulsco Enterprise PWA
 * - Default: network-only
 * - Cache allowlist: same-origin GET safe static assets + /api/public/* (short TTL)
 * - Blocklist: /billing/*, /wallet/*, /admin/*, /auth/*, /edge/*, /marp/*
 * - Offline fallback: /offline.html (document navigations only; never for blocked paths)
 * - CSI telemetry buffering: anonymous UX events in IndexedDB; flush when online (no cookies/tokens)
 */

const VERSION = "2026-02-23";
const CACHE_PREFIX = "pulsco-pwa";

const PRECACHE_NAME = `${CACHE_PREFIX}-precache-${VERSION}`;
const ASSET_CACHE_NAME = `${CACHE_PREFIX}-assets-${VERSION}`;
const API_PUBLIC_CACHE_NAME = `${CACHE_PREFIX}-api-public-${VERSION}`;

const API_PUBLIC_TTL_MS = 60 * 1000;

const TELEMETRY_DB_NAME = "pulsco-csi";
const TELEMETRY_STORE = "events";
const TELEMETRY_MAX_EVENTS = 200;
const TELEMETRY_ENDPOINT = "/api/public/telemetry";
const TELEMETRY_REASON_CODE = "CSI_GATEWAY_ACCESS";
const TELEMETRY_BATCH_SIZE = 25;
const TELEMETRY_FLUSH_COOLDOWN_MS = 60 * 1000;

let lastTelemetryFlushAttempt = 0;

const BLOCKED_PATH_RE = /^\/(billing|wallet|admin|auth|edge|marp)(\/|$)/i;
const API_PUBLIC_PATH_RE = /^\/api\/public\//i;
const SAFE_PUBLIC_ASSET_RE =
  /^(?:\/_next\/static\/|\/icons\/|\/favicon\.ico$|\/offline\.html$|\/manifest\.webmanifest$|\/pwa-precache\.json$)/i;

const PRECACHE_URLS = [
  "/offline.html",
  "/manifest.webmanifest",
  "/favicon.ico",
  "/icons/icon-16x16.png",
  "/icons/icon-32x32.png",
  "/icons/icon-152x152.jpeg",
  "/icons/icon-192x192.jpeg",
  "/icons/icon-512x512.jpeg",
  "/icons/icon-152x152-maskable.jpeg",
  "/icons/icon-512x512-maskable.jpeg"
];

function isSameOrigin(url) {
  return url.origin === self.location.origin;
}

function isBlockedPath(pathname) {
  return BLOCKED_PATH_RE.test(pathname);
}

function isCacheableAssetPath(pathname) {
  return SAFE_PUBLIC_ASSET_RE.test(pathname);
}

function isApiPublicPath(pathname) {
  return API_PUBLIC_PATH_RE.test(pathname);
}

function isCacheableResponse(response) {
  if (!response || !response.ok) return false;
  if (response.type !== "basic") return false;
  const cacheControl = (response.headers.get("cache-control") || "").toLowerCase();
  if (cacheControl.includes("no-store") || cacheControl.includes("private")) return false;
  if (response.headers.has("set-cookie")) return false;
  return true;
}

function getDestination(request) {
  return request.destination || "";
}

async function precache() {
  const cache = await caches.open(PRECACHE_NAME);
  await cache.addAll(PRECACHE_URLS);

  // Optional: build-time generated list of Next.js JS/CSS bundles.
  // Generated by: `node scripts/pwa/generate-precache.mjs --app <appDir>`
  try {
    const res = await fetch("/pwa-precache.json", { cache: "no-store" });
    if (!res.ok) return;
    const list = await res.json();
    if (!Array.isArray(list)) return;

    const urls = list.filter((u) => {
      if (typeof u !== "string") return false;
      if (!u.startsWith("/_next/static/")) return false;
      return u.endsWith(".js") || u.endsWith(".css");
    });

    await Promise.all(
      urls.map(async (u) => {
        try {
          await cache.add(u);
        } catch {
          // Ignore individual failures (e.g., transient build/asset mismatch)
        }
      })
    );
  } catch {
    // No-op: precache list is optional
  }
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      await precache();
      await self.skipWaiting();
    })()
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.map((name) => {
          if (!name.startsWith(CACHE_PREFIX)) return undefined;
          if ([PRECACHE_NAME, ASSET_CACHE_NAME, API_PUBLIC_CACHE_NAME].includes(name)) return undefined;
          return caches.delete(name);
        })
      );

      await self.clients.claim();
      await flushTelemetry({ force: true });
    })()
  );
});

async function cacheApiPublicResponse(cache, request, response) {
  const headers = new Headers(response.headers);
  headers.set("x-sw-cache-time", String(Date.now()));
  const body = await response.clone().arrayBuffer();
  const responseToCache = new Response(body, {
    status: response.status,
    statusText: response.statusText,
    headers
  });
  await cache.put(request, responseToCache);
}

function isApiPublicFresh(response) {
  const ts = Number(response.headers.get("x-sw-cache-time") || 0);
  if (!ts) return false;
  return Date.now() - ts <= API_PUBLIC_TTL_MS;
}

async function handleApiPublic(request) {
  const cache = await caches.open(API_PUBLIC_CACHE_NAME);
  const cached = await cache.match(request);

  if (cached && isApiPublicFresh(cached)) return cached;

  try {
    const response = await fetch(request);
    if (isCacheableResponse(response)) {
      await cacheApiPublicResponse(cache, request, response);
    }
    await maybeFlushTelemetry();
    return response;
  } catch (err) {
    if (cached) return cached;
    throw err;
  }
}

async function handleAsset(request, url, event) {
  if (!isCacheableAssetPath(url.pathname)) {
    return fetch(request);
  }

  const cache = await caches.open(ASSET_CACHE_NAME);
  const cached = await cache.match(request, { ignoreSearch: true });

  const update = (async () => {
    try {
      const response = await fetch(request);
      if (isCacheableResponse(response) && isCacheableAssetPath(url.pathname)) {
        await cache.put(request, response.clone());
      }
    } catch {
      // Ignore network errors during revalidation
    }
  })();

  if (cached) {
    event.waitUntil(update);
    event.waitUntil(maybeFlushTelemetry());
    return cached;
  }

  const response = await fetch(request);
  if (isCacheableResponse(response)) {
    event.waitUntil(cache.put(request, response.clone()));
  }
  event.waitUntil(maybeFlushTelemetry());
  return response;
}

async function handleDocument(request, url) {
  if (isBlockedPath(url.pathname)) {
    return fetch(request);
  }

  try {
    const response = await fetch(request);
    await maybeFlushTelemetry();
    return response;
  } catch (err) {
    const cache = await caches.open(PRECACHE_NAME);
    const offline = await cache.match("/offline.html", { ignoreSearch: true });
    return (
      offline ||
      new Response("Offline", {
        status: 503,
        headers: { "content-type": "text/plain; charset=utf-8" }
      })
    );
  }
}

self.addEventListener("fetch", (event) => {
  const request = event.request;

  event.respondWith(
    (async () => {
      const url = new URL(request.url);

      if (!isSameOrigin(url)) return fetch(request);
      if (request.method !== "GET") return fetch(request);
      if (isBlockedPath(url.pathname)) return fetch(request);

      const destination = getDestination(request);

      if (request.mode === "navigate" || destination === "document") {
        return handleDocument(request, url);
      }

      if (isApiPublicPath(url.pathname)) {
        return handleApiPublic(request);
      }

      if (["script", "style", "image", "font"].includes(destination)) {
        return handleAsset(request, url, event);
      }

      // Default: network-only
      const response = await fetch(request);
      event.waitUntil(maybeFlushTelemetry());
      return response;
    })()
  );
});

// -------------------------
// CSI telemetry buffering
// -------------------------

function isPlainObject(value) {
  return Object.prototype.toString.call(value) === "[object Object]";
}

function sanitizeMeta(meta) {
  if (!isPlainObject(meta)) return undefined;

  const forbiddenKeyRe = /(token|auth|authorization|cookie|password|secret|wallet|billing|admin|edge|marp)/i;
  const entries = Object.entries(meta).slice(0, 12);
  const clean = {};

  for (const [key, value] of entries) {
    if (typeof key !== "string" || forbiddenKeyRe.test(key)) continue;
    if (typeof value === "string") {
      clean[key] = value.slice(0, 128);
      continue;
    }
    if (typeof value === "number" && Number.isFinite(value)) {
      clean[key] = value;
      continue;
    }
    if (typeof value === "boolean") {
      clean[key] = value;
      continue;
    }
  }

  return Object.keys(clean).length ? clean : undefined;
}

function sanitizeTelemetryPayload(payload) {
  if (!isPlainObject(payload)) return null;

  const event = typeof payload.event === "string" ? payload.event.trim() : "";
  if (!event || event.length > 64) return null;

  const ts =
    typeof payload.ts === "number" && Number.isFinite(payload.ts) ? Math.floor(payload.ts) : Date.now();

  let path;
  if (typeof payload.path === "string") {
    const cleaned = payload.path.split("?")[0].slice(0, 256);
    if (cleaned && !isBlockedPath(cleaned)) path = cleaned;
  }

  const meta = sanitizeMeta(payload.meta);

  const safe = { event, ts, path, meta };
  try {
    if (JSON.stringify(safe).length > 2048) return null;
  } catch {
    return null;
  }

  return safe;
}

function openTelemetryDb() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(TELEMETRY_DB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(TELEMETRY_STORE)) {
        const store = db.createObjectStore(TELEMETRY_STORE, { keyPath: "id", autoIncrement: true });
        store.createIndex("ts", "ts");
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function telemetryCount() {
  const db = await openTelemetryDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(TELEMETRY_STORE, "readonly");
    const store = tx.objectStore(TELEMETRY_STORE);
    const req = store.count();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
    tx.oncomplete = () => db.close();
    tx.onabort = () => {
      db.close();
      reject(tx.error);
    };
  });
}

async function telemetryAdd(record) {
  const db = await openTelemetryDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(TELEMETRY_STORE, "readwrite");
    const store = tx.objectStore(TELEMETRY_STORE);
    const req = store.add(record);
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
    tx.oncomplete = () => db.close();
    tx.onabort = () => {
      db.close();
      reject(tx.error);
    };
  });
}

async function telemetryDelete(ids) {
  const db = await openTelemetryDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(TELEMETRY_STORE, "readwrite");
    const store = tx.objectStore(TELEMETRY_STORE);
    for (const id of ids) store.delete(id);
    tx.oncomplete = () => {
      db.close();
      resolve();
    };
    tx.onerror = () => {
      db.close();
      reject(tx.error);
    };
    tx.onabort = () => {
      db.close();
      reject(tx.error);
    };
  });
}

async function telemetryGetBatch(limit) {
  const db = await openTelemetryDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(TELEMETRY_STORE, "readonly");
    const store = tx.objectStore(TELEMETRY_STORE);
    const out = [];
    const req = store.openCursor();

    req.onsuccess = () => {
      const cursor = req.result;
      if (!cursor || out.length >= limit) {
        resolve(out);
        return;
      }
      out.push(cursor.value);
      cursor.continue();
    };

    req.onerror = () => reject(req.error);
    tx.oncomplete = () => db.close();
    tx.onabort = () => {
      db.close();
      reject(tx.error);
    };
  });
}

async function telemetryTrimToMax(max) {
  const count = await telemetryCount();
  const extra = count - max;
  if (extra <= 0) return;

  const db = await openTelemetryDb();
  await new Promise((resolve, reject) => {
    const tx = db.transaction(TELEMETRY_STORE, "readwrite");
    const store = tx.objectStore(TELEMETRY_STORE);
    let removed = 0;
    const req = store.openCursor();

    req.onsuccess = () => {
      const cursor = req.result;
      if (!cursor || removed >= extra) {
        resolve();
        return;
      }
      store.delete(cursor.primaryKey);
      removed += 1;
      cursor.continue();
    };

    req.onerror = () => reject(req.error);
    tx.oncomplete = () => db.close();
    tx.onabort = () => {
      db.close();
      reject(tx.error);
    };
  });
}

async function enqueueTelemetry(payload) {
  const safe = sanitizeTelemetryPayload(payload);
  if (!safe) return;

  await telemetryAdd(safe);
  await telemetryTrimToMax(TELEMETRY_MAX_EVENTS);
}

async function flushTelemetry({ force = false } = {}) {
  const now = Date.now();
  if (!force && now - lastTelemetryFlushAttempt < TELEMETRY_FLUSH_COOLDOWN_MS) return;
  lastTelemetryFlushAttempt = now;

  for (let i = 0; i < 10; i += 1) {
    const batch = await telemetryGetBatch(TELEMETRY_BATCH_SIZE);
    if (!batch.length) return;

    try {
      const res = await fetch(TELEMETRY_ENDPOINT, {
        method: "POST",
        headers: { "content-type": "application/json" },
        credentials: "omit",
        cache: "no-store",
        body: JSON.stringify({
          schema: "pulsco-csi-v1",
          reason_code: TELEMETRY_REASON_CODE,
          events: batch.map(({ event, ts, path, meta }) => ({ event, ts, path, meta }))
        })
      });

      if (!res.ok) return;

      await telemetryDelete(batch.map((e) => e.id));
    } catch {
      return;
    }
  }
}

async function maybeFlushTelemetry() {
  return flushTelemetry({ force: false });
}

self.addEventListener("message", (event) => {
  const data = event.data;
  if (!data || typeof data !== "object") return;

  if (data.type === "CSI_TELEMETRY") {
    event.waitUntil(enqueueTelemetry(data.payload));
    return;
  }

  if (data.type === "CSI_FLUSH") {
    event.waitUntil(flushTelemetry({ force: true }));
    return;
  }

  if (data.type === "SKIP_WAITING") {
    event.waitUntil(self.skipWaiting());
  }
});


